<script lang="ts">import { onMount } from 'svelte';import { PONG_EVENT,heartbeatEvents } from '$lib/heartbeat';let connected=$state(false);let timer:ReturnType<typeof setTimeout>|null=null;onMount(()=>{const pong=()=>{connected=true;if(timer)clearTimeout(timer);timer=setTimeout(()=>connected=false,60_000);};heartbeatEvents.addEventListener(PONG_EVENT,pong);return()=>{heartbeatEvents.removeEventListener(PONG_EVENT,pong);if(timer)clearTimeout(timer);};});</script><span class:connected class="presence" role="status" aria-label={connected?'Connexion temps réel active':'Connexion temps réel indisponible'}></span><style>.presence{position:fixed;top:1rem;right:1rem;z-index:10;width:.75rem;height:.75rem;border:2px solid #0f172a;border-radius:50%;background:#ef4444;box-shadow:0 0 0 1px rgba(248,250,252,.36)}.presence.connected{background:#22c55e}</style>
